function sample(){const p=blank(32,32,'Orbit courier');const l=p.layers[0];l.name='Courier';const img=p.images[p.cels[0].imageId];const put=(x:number,y:number,c:RGBA)=>{if(x>=0&&y>=0&&x<32&&y<32)img.data.set(c,(y*32+x)*4);};for(let y=5;y<=24;y++)for(let x=6;x<=25;x++){const dx=Math.abs(x-15.5),dy=y-5;if(dx<Math.min(8,dy/2+1)&&y<23){put(x,y,PALETTE[2]);if(dx<5&&y>11)put(x,y,PALETTE[3]);if(x<15&&y>16)put(x,y,PALETTE[4]);}}for(let y=12;y<18;y++)for(let x=12;x<20;x++){put(x,y,PALETTE[5]);if(x>12&&x<19&&y>12&&y<17)put(x,y,PALETTE[7]);}for(let y=20;y<27;y++)for(let x=5;x<10;x++)if(y>26-(x-5))put(x,y,PALETTE[13]);for(let y=20;y<27;y++)for(let x=22;x<27;x++)if(y>26-(26-x))put(x,y,PALETTE[13]);for(let y=23;y<30;y++)for(let x=12;x<20;x++)if(Math.abs(x-15.5)<(30-y)/2){put(x,y,PALETTE[y%2?11:12]);}for(let n=0;n<3;n++){const f=addFrame(p,p.frames[p.frames.length-1].id);const im=p.images[getCel(p,l.id,f.id)!.imageId];for(let y=23;y<32;y++)for(let x=12;x<20;x++){const idx=(y*32+x)*4;im.data.fill(0,idx,idx+4);if(Math.abs(x-15.5)<Math.max(0,(29+(n%2)-y)/2))im.data.set(PALETTE[(y+n)%2?11:12],idx);}}p.tags.push({id:uid(),name:'Cruise',from:p.frames[0].id,to:p.frames[3].id,direction:'pingpong',repeat:0,color:PALETTE[7]});return p;}
