function tick(now:number){if(playing){elapsed+=Math.min(1000,now-lastTick);const tag=project().tags.find(t=>t.id===selectedTag),seq=animationSequence(project(),tag,!!tag?.repeat);let steps=0;while(elapsed>=project().frames.find(f=>f.id===frameId)!.duration&&steps++<100){elapsed-=project().frames.find(f=>f.id===frameId)!.duration;playbackIndex++;if(playbackIndex>=seq.length){if(tag?.repeat){playing=false;$('#play').innerHTML=iconLabel('play','Play');$('#play').setAttribute('aria-label','Play');break;}playbackIndex=0;}frameId=seq[playbackIndex];}render();document.querySelectorAll<HTMLElement>('[data-frame]').forEach(el=>el.classList.toggle('selected',el.dataset.frame===frameId));}lastTick=now;requestAnimationFrame(tick);}
